BEGIN;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, name TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY, title TEXT NOT NULL, subtitle TEXT, author TEXT, locale TEXT NOT NULL DEFAULT 'en', format_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS manuscript_nodes(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, parent_id TEXT REFERENCES manuscript_nodes(id), kind TEXT NOT NULL CHECK(kind IN('book','part','act','chapter','scene','interlude','note','research')), title TEXT NOT NULL, synopsis TEXT, position INTEGER NOT NULL, pov_character_id TEXT, content_path TEXT, content_hash TEXT, word_count INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, UNIQUE(parent_id,position));
CREATE INDEX IF NOT EXISTS idx_nodes_binder ON manuscript_nodes(project_id,parent_id,position) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS document_revisions(id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES manuscript_nodes(id), parent_revision_id TEXT REFERENCES document_revisions(id), revision INTEGER NOT NULL, content_hash TEXT NOT NULL, snapshot_path TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN('autosave','manual','ai-accepted','import','undo')), created_at TEXT NOT NULL, UNIQUE(document_id,revision));
CREATE TABLE IF NOT EXISTS characters(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN('major','supporting','minor')), full_name TEXT NOT NULL, identity_json TEXT NOT NULL CHECK(json_valid(identity_json)), psychology_json TEXT NOT NULL CHECK(json_valid(psychology_json)), notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE INDEX IF NOT EXISTS idx_characters_project ON characters(project_id,role) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS voice_locks(id TEXT PRIMARY KEY, character_id TEXT NOT NULL UNIQUE REFERENCES characters(id) ON DELETE CASCADE, version INTEGER NOT NULL DEFAULT 1, profile_json TEXT NOT NULL CHECK(json_valid(profile_json)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS voice_examples(id TEXT PRIMARY KEY, voice_lock_id TEXT NOT NULL REFERENCES voice_locks(id) ON DELETE CASCADE, approved INTEGER NOT NULL CHECK(approved IN(0,1)), text TEXT NOT NULL, situation TEXT, addressee_character_id TEXT REFERENCES characters(id), emotion TEXT, provenance_node_id TEXT REFERENCES manuscript_nodes(id), author_note TEXT, position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS character_states(id TEXT PRIMARY KEY, character_id TEXT NOT NULL REFERENCES characters(id) ON DELETE CASCADE, effective_from_node_id TEXT NOT NULL REFERENCES manuscript_nodes(id), effective_to_node_id TEXT REFERENCES manuscript_nodes(id), aggregate_json TEXT NOT NULL CHECK(json_valid(aggregate_json)), source TEXT NOT NULL CHECK(source IN('manual','accepted-extraction','revision')), confidence REAL CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1), created_at TEXT NOT NULL, superseded_by_id TEXT REFERENCES character_states(id));
CREATE INDEX IF NOT EXISTS idx_character_states_at ON character_states(character_id,effective_from_node_id,effective_to_node_id);
CREATE TABLE IF NOT EXISTS character_state_facts(id TEXT PRIMARY KEY, state_id TEXT NOT NULL REFERENCES character_states(id) ON DELETE CASCADE, fact_type TEXT NOT NULL, value TEXT NOT NULL, related_entity_id TEXT, status TEXT NOT NULL DEFAULT 'active', provenance_node_id TEXT REFERENCES manuscript_nodes(id), position INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_state_facts_lookup ON character_state_facts(state_id,fact_type,status);
CREATE TABLE IF NOT EXISTS relationships(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, from_character_id TEXT NOT NULL REFERENCES characters(id), to_character_id TEXT NOT NULL REFERENCES characters(id), relationship_type TEXT NOT NULL, profile_json TEXT NOT NULL CHECK(json_valid(profile_json)), trust REAL CHECK(trust BETWEEN -1 AND 1), affection REAL CHECK(affection BETWEEN -1 AND 1), loyalty REAL CHECK(loyalty BETWEEN -1 AND 1), resentment REAL CHECK(resentment BETWEEN -1 AND 1), fear REAL CHECK(fear BETWEEN -1 AND 1), dependency REAL CHECK(dependency BETWEEN -1 AND 1), respect REAL CHECK(respect BETWEEN -1 AND 1), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(from_character_id<>to_character_id), UNIQUE(from_character_id,to_character_id));
CREATE TABLE IF NOT EXISTS relationship_changes(id TEXT PRIMARY KEY, relationship_id TEXT NOT NULL REFERENCES relationships(id) ON DELETE CASCADE, node_id TEXT NOT NULL REFERENCES manuscript_nodes(id), changes_json TEXT NOT NULL CHECK(json_valid(changes_json)), reason TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS character_arcs(id TEXT PRIMARY KEY, character_id TEXT NOT NULL REFERENCES characters(id), title TEXT NOT NULL, arc_json TEXT NOT NULL CHECK(json_valid(arc_json)), status TEXT NOT NULL DEFAULT 'draft', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS arc_beats(id TEXT PRIMARY KEY, arc_id TEXT NOT NULL REFERENCES character_arcs(id) ON DELETE CASCADE, beat_type TEXT NOT NULL, node_id TEXT REFERENCES manuscript_nodes(id), description TEXT NOT NULL, position INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS bible_entities(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, entity_type TEXT NOT NULL, name TEXT NOT NULL, summary TEXT, canon_status TEXT NOT NULL CHECK(canon_status IN('canon','draft','possible','rejected','superseded','unknown')), superseded_by_id TEXT REFERENCES bible_entities(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE INDEX IF NOT EXISTS idx_bible_entities ON bible_entities(project_id,entity_type,canon_status) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS bible_facts(id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES bible_entities(id) ON DELETE CASCADE, field_name TEXT NOT NULL, value_json TEXT NOT NULL CHECK(json_valid(value_json)), canon_status TEXT NOT NULL CHECK(canon_status IN('canon','draft','possible','rejected','superseded','unknown')), valid_from_node_id TEXT REFERENCES manuscript_nodes(id), valid_to_node_id TEXT REFERENCES manuscript_nodes(id), provenance_node_id TEXT REFERENCES manuscript_nodes(id), extraction_run_id TEXT, reviewed_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS timeline_events(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT, story_time_start TEXT, story_time_end TEXT, order_key REAL NOT NULL, node_id TEXT REFERENCES manuscript_nodes(id), canon_status TEXT NOT NULL DEFAULT 'draft', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS timeline_participants(event_id TEXT NOT NULL REFERENCES timeline_events(id) ON DELETE CASCADE, entity_id TEXT NOT NULL, role TEXT, PRIMARY KEY(event_id,entity_id));
CREATE TABLE IF NOT EXISTS plot_threads(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title TEXT NOT NULL, thread_type TEXT NOT NULL, status TEXT NOT NULL, opened_node_id TEXT REFERENCES manuscript_nodes(id), resolved_node_id TEXT REFERENCES manuscript_nodes(id), description TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_configs(id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id) ON DELETE CASCADE, provider_type TEXT NOT NULL, label TEXT NOT NULL, base_url TEXT, credential_ref TEXT, config_json TEXT NOT NULL CHECK(json_valid(config_json)), enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS task_routes(project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, task TEXT NOT NULL, provider_config_id TEXT NOT NULL REFERENCES provider_configs(id), model_id TEXT NOT NULL, settings_json TEXT NOT NULL CHECK(json_valid(settings_json)), PRIMARY KEY(project_id,task));
CREATE TABLE IF NOT EXISTS context_packages(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, task TEXT NOT NULL, target_json TEXT NOT NULL CHECK(json_valid(target_json)), story_position_id TEXT REFERENCES manuscript_nodes(id), exclusions_json TEXT NOT NULL CHECK(json_valid(exclusions_json)), estimated_input_tokens INTEGER NOT NULL, token_budget INTEGER NOT NULL, estimated_cost_json TEXT CHECK(estimated_cost_json IS NULL OR json_valid(estimated_cost_json)), assembler_version TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS context_items(id TEXT PRIMARY KEY, package_id TEXT NOT NULL REFERENCES context_packages(id) ON DELETE CASCADE, source TEXT NOT NULL, source_entity_id TEXT, source_version TEXT, title TEXT NOT NULL, content TEXT NOT NULL, relevance REAL NOT NULL CHECK(relevance BETWEEN 0 AND 1), reason TEXT NOT NULL, token_estimate INTEGER NOT NULL, pinned INTEGER NOT NULL DEFAULT 0, content_hash TEXT NOT NULL, position INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_runs(id TEXT PRIMARY KEY, context_package_id TEXT NOT NULL REFERENCES context_packages(id), provider_config_id TEXT NOT NULL REFERENCES provider_configs(id), model_id TEXT NOT NULL, task TEXT NOT NULL, prompt_template_version TEXT NOT NULL, request_metadata_json TEXT NOT NULL CHECK(json_valid(request_metadata_json)), response_metadata_json TEXT CHECK(response_metadata_json IS NULL OR json_valid(response_metadata_json)), status TEXT NOT NULL CHECK(status IN('queued','running','succeeded','failed','cancelled')), error_redacted TEXT, started_at TEXT, completed_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS change_sets(id TEXT PRIMARY KEY, ai_run_id TEXT REFERENCES ai_runs(id), project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS change_proposals(id TEXT PRIMARY KEY, change_set_id TEXT NOT NULL REFERENCES change_sets(id) ON DELETE CASCADE, document_id TEXT NOT NULL REFERENCES manuscript_nodes(id), base_revision INTEGER NOT NULL, base_content_hash TEXT NOT NULL, range_from INTEGER NOT NULL, range_to INTEGER NOT NULL, before_text TEXT NOT NULL, after_text TEXT NOT NULL, issue TEXT NOT NULL, rationale TEXT NOT NULL, evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json)), strategies_json TEXT NOT NULL CHECK(json_valid(strategies_json)), context_package_id TEXT NOT NULL REFERENCES context_packages(id), parent_proposal_id TEXT REFERENCES change_proposals(id), created_at TEXT NOT NULL, CHECK(range_from<=range_to));
CREATE INDEX IF NOT EXISTS idx_proposals_target ON change_proposals(document_id,base_revision);
CREATE TABLE IF NOT EXISTS proposal_decisions(id TEXT PRIMARY KEY, proposal_id TEXT NOT NULL REFERENCES change_proposals(id), decision TEXT NOT NULL CHECK(decision IN('accepted','rejected','deferred','edited')), decided_at TEXT NOT NULL, note TEXT, resulting_revision_id TEXT REFERENCES document_revisions(id));
CREATE TABLE IF NOT EXISTS tags(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name TEXT NOT NULL, color TEXT, UNIQUE(project_id,name));
CREATE TABLE IF NOT EXISTS entity_tags(tag_id TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, PRIMARY KEY(tag_id,entity_type,entity_id));
CREATE TABLE IF NOT EXISTS snapshots(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, path TEXT NOT NULL, manifest_hash TEXT NOT NULL, reason TEXT NOT NULL, verified_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS background_jobs(id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id) ON DELETE CASCADE, job_type TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), status TEXT NOT NULL CHECK(status IN('queued','running','succeeded','failed','cancelled')), progress REAL NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 1), error_redacted TEXT, attempts INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_jobs_queue ON background_jobs(status,created_at);
CREATE TABLE IF NOT EXISTS project_settings(project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, key TEXT NOT NULL, value_json TEXT NOT NULL CHECK(json_valid(value_json)), updated_at TEXT NOT NULL, PRIMARY KEY(project_id,key));
CREATE VIRTUAL TABLE IF NOT EXISTS manuscript_fts USING fts5(document_id UNINDEXED,title,content,tokenize='unicode61');
CREATE VIRTUAL TABLE IF NOT EXISTS knowledge_fts USING fts5(entity_id UNINDEXED,name,content,tokenize='unicode61');
INSERT OR IGNORE INTO schema_migrations(version,name,applied_at) VALUES(1,'initial',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
PRAGMA user_version=1;
COMMIT;
